type Field={key:string;label:string;type?:string;options?:{value:string;label:string}[];required?:boolean;help?:string};
function FieldsForm({fields,initial,submit,label='Save'}:{fields:Field[];initial:Row;submit:(r:Row)=>Promise<void>;label?:string}){const [values,setValues]=useState(initial),[busy,setBusy]=useState(false),[error,setError]=useState('');return <form className="fo-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await submit(values);}catch(e:any){setError(e.message);}finally{setBusy(false);}}}><fieldset disabled={busy}><div className="fo-fields">{fields.map(f=><label key={f.key} className={f.type==='textarea'?'fo-wide':''}>{f.label}{f.type==='checkbox'?<input type="checkbox" checked={!!values[f.key]} onChange={e=>setValues({...values,[f.key]:e.target.checked})}/>:f.type==='multiselect'?<span className="fo-checkboxes">{f.options?.map(o=><label key={o.value}><input type="checkbox" checked={(values[f.key]||[]).includes(o.value)} onChange={e=>setValues({...values,[f.key]:e.target.checked?[...(values[f.key]||[]),o.value]:(values[f.key]||[]).filter((v:string)=>v!==o.value)})}/>{o.label}</label>)}</span>:f.type==='select'?<select required={f.required} value={values[f.key]??''} onChange={e=>setValues({...values,[f.key]:e.target.value})}>{f.options?.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:f.type==='textarea'?<textarea required={f.required} value={values[f.key]??''} onChange={e=>setValues({...values,[f.key]:e.target.value})}/>:<input required={f.required} type={f.type||'text'} min={f.type==='number'?0:undefined} step={f.type==='number'?'0.01':undefined} value={values[f.key]??''} onChange={e=>setValues({...values,[f.key]:e.target.value})}/>} {f.help&&<small>{f.help}</small>}</label>)}</div>{error&&<p className="fo-error" role="alert">{error}</p>}<button className="button dark" type="submit">{busy?'Saving…':label}</button></fieldset></form>;}
