function CollectionForm({student,session,invoices,selectedIds,onDone}:{student:Row;session:string;invoices:Row[];selectedIds:string[];onDone:()=>void}){
 const [ids,setIds]=useState(selectedIds),[values,setValues]=useState({amount:(total(invoices.filter(i=>selectedIds.includes(i.id)),'outstanding')/100).toFixed(2),method:'Cash',reference:'',chequeNumber:'',bank:'',chequeDate:''}),[preview,setPreview]=useState<Row|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[requestKey]=useState(uid);
 const change=(key:string,value:string)=>{setValues(v=>({...v,[key]:value}));setPreview(null);};const payload={...values,studentId:student.id,session,invoiceIds:ids,idempotencyKey:requestKey};
 return <form className="fo-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{if(preview){await api('/fees/office/collections','POST',{...payload,token:preview.token});onDone();}else setPreview(await api('/fees/office/collections/preview','POST',payload));}catch(e:any){setError(e.message);}finally{setBusy(false);}}}><fieldset disabled={busy}><h3>{student.name} · {student.className}</h3><p>Select invoices to settle. Payments are allocated by due date. Any excess remains an advance when enabled.</p><div className="fo-invoice-select">{invoices.map(i=><label key={i.id}><input type="checkbox" checked={ids.includes(i.id)} onChange={e=>{setIds(e.target.checked?[...ids,i.id]:ids.filter(id=>id!==i.id));setPreview(null);}}/>{i.number} · Due {i.dueDate} · {money(i.outstanding)}</label>)}</div><div className="fo-fields"><label>Amount received (₹)<input required type="number" min="0.01" step="0.01" value={values.amount} onChange={e=>change('amount',e.target.value)}/></label><label>Payment method<select value={values.method} onChange={e=>change('method',e.target.value)}>{['Cash','UPI','Bank Transfer','Cheque','Card'].map(m=><option key={m}>{m}</option>)}</select></label><label>Transaction reference<input required={values.method!=='Cash'} value={values.reference} onChange={e=>change('reference',e.target.value)}/></label>{values.method==='Cheque'&&['chequeNumber','bank','chequeDate'].map(key=><label key={key}>{({chequeNumber:'Cheque number',bank:'Bank',chequeDate:'Cheque date'} as any)[key]}<input required type={key==='chequeDate'?'date':'text'} value={(values as any)[key]} onChange={e=>change(key,e.target.value)}/></label>)}</div>{preview&&<div className="fo-payment-preview"><h3>Confirm payment allocation</h3>{preview.allocations.map((a:Row)=><p key={a.invoiceId}>{a.number}: {money(a.amount)} · Remaining {money(a.outstanding-a.amount)}</p>)}<p>Advance balance added: <strong>{money(preview.advance)}</strong></p><p>Total received: <strong>{money(preview.amount)}</strong></p>{values.method!=='Cash'&&<p>This collection will await independent bank verification. A receipt will be issued after verification.</p>}</div>}{error&&<p className="fo-error" role="alert">{error}</p>}<button className="button dark" type="submit">{busy?'Processing…':preview?'Confirm collection':'Preview payment allocation'}</button></fieldset></form>;
}
function InstallmentForm({invoice,onDone}:{invoice:Row;onDone:()=>void}){const [rows,setRows]=useState([{amount:(invoice.amount/100).toFixed(2),dueDate:invoice.dueDate}]),[error,setError]=useState(''),[busy,setBusy]=useState(false);return <form className="fo-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await api(`/fees/office/invoices/${invoice.id}/installments`,'POST',{rows});onDone();}catch(e:any){setError(e.message);}finally{setBusy(false);}}}><fieldset disabled={busy}><p>Installments must total {money(invoice.amount)}. Choose custom amounts and dates for monthly, quarterly, half-yearly or annual plans.</p>{rows.map((r,n)=><div className="fo-fields" key={n}><label>Installment {n+1} amount (₹)<input type="number" min="0.01" step="0.01" required value={r.amount} onChange={e=>setRows(rows.map((x,i)=>i===n?{...x,amount:e.target.value}:x))}/></label><label>Due date<input type="date" required value={r.dueDate} onChange={e=>setRows(rows.map((x,i)=>i===n?{...x,dueDate:e.target.value}:x))}/></label><button type="button" disabled={rows.length===1} onClick={()=>setRows(rows.filter((_,i)=>i!==n))}>Remove installment</button></div>)}<button type="button" onClick={()=>setRows([...rows,{amount:'',dueDate:invoice.dueDate}])}>Add installment</button>{error&&<p className="fo-error" role="alert">{error}</p>}<button type="submit" className="button dark">Save installment plan</button></fieldset></form>;}
